<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Models\InventoryStock;
use App\Models\Product;
use App\Models\PurchaseInvoice;
use App\Models\PurchaseOrder;
use App\Models\PurchaseReturn;
use App\Models\Supplier;
use App\Models\SupplierLedger;
use App\Models\SupplierPayment;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Support\BusinessAccess;

class PurchaseController extends Controller
{
    private function businessId(Request $request): int { abort_unless($request->user()->business_id, 422, 'Create a business first.'); return $request->user()->business_id; }
    private function number(string $prefix, string $model): string { return $prefix.'-'.now()->format('Ymd').'-'.str_pad((string)($model::whereDate('created_at', today())->count() + 1), 4, '0', STR_PAD_LEFT); }
    private function branch(int $branchId, int $business): void { abort_unless(DB::table('branches')->where('id', $branchId)->where('business_id', $business)->exists(), 422, 'Selected branch does not belong to this business.'); $user=request()->user(); if(!in_array($user->role,['owner','super_admin'],true)) abort_unless((int)$user->branch_id===$branchId,403,'You can only access your assigned branch.'); }

    public function suppliers(Request $request) { return response()->json(['data' => Supplier::where('business_id', $this->businessId($request))->latest()->paginate($request->integer('per_page', 30))]); }
    public function storeSupplier(Request $request)
    {
        $business = $this->businessId($request);
        $data = $request->validate(['branch_id'=>['nullable','integer','exists:branches,id'],'name'=>['required','string','max:150'],'contact_person'=>['nullable','string','max:120'],'mobile'=>['nullable','string','max:20'],'email'=>['nullable','email'],'address'=>['nullable','string'],'credit_limit'=>['nullable','numeric','min:0']]);
        if (!empty($data['branch_id'])) $this->branch($data['branch_id'], $business);
        return response()->json(['data'=>Supplier::create([...$data,'business_id'=>$business])], 201);
    }
    public function updateSupplier(Request $request, Supplier $supplier)
    {
        $business=$this->businessId($request); abort_unless($supplier->business_id===$business,403);
        $data=$request->validate(['branch_id'=>['nullable','integer','exists:branches,id'],'name'=>['sometimes','string','max:150'],'contact_person'=>['nullable','string','max:120'],'mobile'=>['nullable','string','max:20'],'email'=>['nullable','email'],'address'=>['nullable','string'],'credit_limit'=>['nullable','numeric','min:0'],'is_active'=>['nullable','boolean']]);
        if (!empty($data['branch_id'])) $this->branch($data['branch_id'],$business); $supplier->update($data); return response()->json(['data'=>$supplier->fresh()]);
    }
    public function supplierLedger(Request $request, Supplier $supplier) { abort_unless($supplier->business_id===$this->businessId($request),403); if($supplier->branch_id)$this->branch($supplier->branch_id,$supplier->business_id); return response()->json(['data'=>['supplier'=>$supplier,'entries'=>$supplier->ledgers()->latest('entry_date')->paginate($request->integer('per_page',50))]]); }

    public function orders(Request $request) { $query=PurchaseOrder::with(['supplier','branch','items'])->where('business_id',$this->businessId($request)); BusinessAccess::scopeBranch($query,$request); return response()->json(['data'=>$query->latest('order_date')->paginate($request->integer('per_page',20))]); }
    public function storeOrder(Request $request)
    {
        $business=$this->businessId($request); $data=$this->documentData($request, false); $this->branch($data['branch_id'],$business);
        return DB::transaction(function() use($data,$business,$request){$supplier=Supplier::where('business_id',$business)->findOrFail($data['supplier_id']); [$subtotal,$items]=$this->items($data['items'],$business); $total=$subtotal-($data['discount']??0)+($data['vat']??0); $order=PurchaseOrder::create(['business_id'=>$business,'branch_id'=>$data['branch_id'],'supplier_id'=>$supplier->id,'user_id'=>$request->user()->id,'order_number'=>$this->number('PO',PurchaseOrder::class),'order_date'=>$data['document_date']??today(),'subtotal'=>$subtotal,'discount'=>$data['discount']??0,'vat'=>$data['vat']??0,'grand_total'=>$total,'status'=>'ordered','notes'=>$data['notes']??null]); foreach($items as $item)$order->items()->create(['product_id'=>$item['product']->id,'product_name'=>$item['product']->name,'ordered_quantity'=>$item['row']['quantity'],'unit_cost'=>$item['cost'],'line_total'=>$item['line']]); return response()->json(['data'=>$order->load('items')],201);});
    }
    public function invoices(Request $request) { $query=PurchaseInvoice::with(['supplier','branch','items'])->where('business_id',$this->businessId($request)); BusinessAccess::scopeBranch($query,$request); return response()->json(['data'=>$query->latest('invoice_date')->paginate($request->integer('per_page',20))]); }
    public function showInvoice(Request $request, PurchaseInvoice $invoice) { abort_unless($invoice->business_id===$this->businessId($request),403); $this->branch($invoice->branch_id,$invoice->business_id); return response()->json(['data'=>$invoice->load(['supplier','branch','items.product','order'])]); }
    public function storeInvoice(Request $request)
    {
        $business=$this->businessId($request); $data=$this->documentData($request, true); $this->branch($data['branch_id'],$business);
        return DB::transaction(function() use($data,$business,$request){$supplier=Supplier::where('business_id',$business)->findOrFail($data['supplier_id']); [$subtotal,$items]=$this->items($data['items'],$business); $total=$subtotal-($data['discount']??0)+($data['vat']??0); $paid=$data['paid_amount']??0; abort_if($paid>$total,422,'Paid amount cannot exceed purchase total.'); if(!empty($data['purchase_order_id']))PurchaseOrder::where('business_id',$business)->findOrFail($data['purchase_order_id']); $invoice=PurchaseInvoice::create(['business_id'=>$business,'branch_id'=>$data['branch_id'],'supplier_id'=>$supplier->id,'purchase_order_id'=>$data['purchase_order_id']??null,'user_id'=>$request->user()->id,'invoice_number'=>$this->number('PINV',PurchaseInvoice::class),'supplier_invoice_number'=>$data['supplier_invoice_number']??null,'invoice_date'=>$data['document_date']??today(),'subtotal'=>$subtotal,'discount'=>$data['discount']??0,'vat'=>$data['vat']??0,'grand_total'=>$total,'paid_amount'=>$paid,'payment_status'=>$paid==0?'due':($paid==$total?'paid':'partial'),'status'=>'draft','notes'=>$data['notes']??null]); foreach($items as $item)$invoice->items()->create(['product_id'=>$item['product']->id,'product_name'=>$item['product']->name,'quantity'=>$item['row']['quantity'],'unit_cost'=>$item['cost'],'line_total'=>$item['line']]); return response()->json(['data'=>$invoice->load('items')],201);});
    }
    public function receive(Request $request, PurchaseInvoice $invoice)
    {
        $business=$this->businessId($request); abort_unless($invoice->business_id===$business,403); $this->branch($invoice->branch_id,$business); abort_if($invoice->status==='received',422,'This purchase has already been received.');
        return DB::transaction(function() use($invoice){ foreach($invoice->items as $item){$stock=InventoryStock::lockForUpdate()->firstOrCreate(['branch_id'=>$invoice->branch_id,'product_id'=>$item->product_id],['quantity'=>0,'reorder_level'=>0]); $oldQty=(float)$stock->quantity; $newQty=$oldQty+(float)$item->quantity; $product=$item->product; $average=$newQty>0?(($oldQty*(float)$product->purchase_price)+((float)$item->quantity*(float)$item->unit_cost))/$newQty:(float)$item->unit_cost; $stock->update(['quantity'=>$newQty]); $product->update(['purchase_price'=>round($average,2)]); }
            $due=(float)$invoice->grand_total-(float)$invoice->paid_amount; $supplier=$invoice->supplier; abort_if($supplier->credit_limit>0 && $supplier->current_due+$due>$supplier->credit_limit,422,'Supplier credit limit exceeded.'); $purchaseBalance=$supplier->current_due+(float)$invoice->grand_total; SupplierLedger::create(['supplier_id'=>$supplier->id,'branch_id'=>$invoice->branch_id,'purchase_invoice_id'=>$invoice->id,'entry_date'=>$invoice->invoice_date,'type'=>'purchase','reference'=>$invoice->invoice_number,'debit'=>$invoice->grand_total,'credit'=>0,'balance'=>$purchaseBalance]); $balance=$supplier->current_due+$due; if($invoice->paid_amount>0){$payment=SupplierPayment::create(['business_id'=>$invoice->business_id,'branch_id'=>$invoice->branch_id,'supplier_id'=>$supplier->id,'purchase_invoice_id'=>$invoice->id,'user_id'=>$invoice->user_id,'receipt_number'=>'SPAY-'.now()->format('YmdHis').'-'.random_int(100,999),'payment_date'=>$invoice->invoice_date,'amount'=>$invoice->paid_amount,'method'=>'cash','notes'=>'Payment recorded with '.$invoice->invoice_number]);SupplierLedger::create(['supplier_id'=>$supplier->id,'branch_id'=>$invoice->branch_id,'purchase_invoice_id'=>$invoice->id,'supplier_payment_id'=>$payment->id,'entry_date'=>$invoice->invoice_date,'type'=>'payment','reference'=>$payment->receipt_number,'debit'=>0,'credit'=>$invoice->paid_amount,'balance'=>$balance]);} $supplier->update(['current_due'=>$balance,'due_since'=>$balance>0?($supplier->due_since??$invoice->invoice_date):null]);
            $invoice->update(['status'=>'received','received_at'=>now()]); if($invoice->purchase_order_id)$invoice->order?->update(['status'=>'received']); return response()->json(['data'=>$invoice->fresh(['items.product','supplier'])]); });
    }
    public function paySupplier(Request $request)
    {
        $business=$this->businessId($request); $data=$request->validate(['branch_id'=>['required','integer','exists:branches,id'],'supplier_id'=>['required','integer','exists:suppliers,id'],'amount'=>['required','numeric','gt:0'],'method'=>['required','in:cash,bank,bkash,nagad'],'transaction_id'=>['nullable','string','max:100'],'payment_date'=>['nullable','date'],'notes'=>['nullable','string']]); $this->branch($data['branch_id'],$business); if($data['method']!=='cash')abort_if(empty($data['transaction_id']),422,'Transaction ID is required for digital payments.');
        return DB::transaction(function()use($data,$business,$request){$supplier=Supplier::where('business_id',$business)->findOrFail($data['supplier_id']); abort_if($data['amount']>$supplier->current_due,422,'Payment exceeds supplier due.'); $payment=SupplierPayment::create([...$data,'business_id'=>$business,'user_id'=>$request->user()->id,'payment_date'=>$data['payment_date']??today(),'receipt_number'=>$this->number('SPAY',SupplierPayment::class)]); $balance=$supplier->current_due-$data['amount']; $supplier->update(['current_due'=>$balance,'due_since'=>$balance==0?null:$supplier->due_since]); SupplierLedger::create(['supplier_id'=>$supplier->id,'branch_id'=>$data['branch_id'],'supplier_payment_id'=>$payment->id,'entry_date'=>$payment->payment_date,'type'=>'payment','reference'=>$payment->receipt_number,'debit'=>0,'credit'=>$payment->amount,'balance'=>$balance,'notes'=>$data['notes']??null]); return response()->json(['data'=>$payment->load('supplier')],201);});
    }
    public function supplierPayments(Request $request) { $query=SupplierPayment::with(['supplier','invoice:id,invoice_number'])->where('business_id',$this->businessId($request)); BusinessAccess::scopeBranch($query,$request); return response()->json(['data'=>$query->latest('payment_date')->paginate($request->integer('per_page',20))]); }
    public function returnPurchase(Request $request, PurchaseInvoice $invoice)
    {
        $business=$this->businessId($request); abort_unless($invoice->business_id===$business,403); $this->branch($invoice->branch_id,$business); abort_if($invoice->status!=='received',422,'Receive the purchase before creating a return.'); $data=$request->validate(['return_date'=>['nullable','date'],'notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id'],'items.*.quantity'=>['required','numeric','gt:0']]);
        return DB::transaction(function()use($invoice,$data){$total=0;$prepared=[];foreach($data['items'] as $row){$line=$invoice->items()->where('product_id',$row['product_id'])->firstOrFail();$already=DB::table('purchase_return_items')->join('purchase_returns','purchase_returns.id','=','purchase_return_items.purchase_return_id')->where('purchase_returns.purchase_invoice_id',$invoice->id)->where('purchase_return_items.product_id',$row['product_id'])->sum('purchase_return_items.quantity');abort_if($already+$row['quantity']>$line->quantity,422,'Return quantity exceeds received quantity.');$stock=InventoryStock::lockForUpdate()->where('branch_id',$invoice->branch_id)->where('product_id',$row['product_id'])->firstOrFail();abort_if($stock->quantity<$row['quantity'],422,'Insufficient current stock for return.');$amount=$row['quantity']*$line->unit_cost;$total+=$amount;$prepared[]=compact('row','line','stock','amount');}$return=PurchaseReturn::create(['business_id'=>$invoice->business_id,'branch_id'=>$invoice->branch_id,'supplier_id'=>$invoice->supplier_id,'purchase_invoice_id'=>$invoice->id,'user_id'=>auth()->id(),'return_number'=>$this->number('PRET',PurchaseReturn::class),'return_date'=>$data['return_date']??today(),'total_amount'=>$total,'notes'=>$data['notes']??null]);foreach($prepared as $item){$item['stock']->decrement('quantity',$item['row']['quantity']);$return->items()->create(['product_id'=>$item['line']->product_id,'quantity'=>$item['row']['quantity'],'unit_cost'=>$item['line']->unit_cost,'line_total'=>$item['amount']]);}$supplier=$invoice->supplier;$balance=max(0,$supplier->current_due-$total);$supplier->update(['current_due'=>$balance,'due_since'=>$balance==0?null:$supplier->due_since]);SupplierLedger::create(['supplier_id'=>$supplier->id,'branch_id'=>$invoice->branch_id,'purchase_invoice_id'=>$invoice->id,'entry_date'=>$return->return_date,'type'=>'return','reference'=>$return->return_number,'debit'=>0,'credit'=>$total,'balance'=>$balance,'notes'=>$return->notes]);return response()->json(['data'=>$return->load('items')],201);});
    }
    public function report(Request $request)
    {
        $business=$this->businessId($request); $from=$request->filled('from')?$request->date('from'):now()->startOfMonth();$to=$request->filled('to')?$request->date('to'):now()->endOfMonth();$purchases=PurchaseInvoice::where('business_id',$business)->where('status','received')->whereBetween('invoice_date',[$from,$to]); BusinessAccess::scopeBranch($purchases,$request); $payments=SupplierPayment::where('business_id',$business)->whereBetween('payment_date',[$from,$to]);BusinessAccess::scopeBranch($payments,$request);$returns=PurchaseReturn::where('business_id',$business)->whereBetween('return_date',[$from,$to]);BusinessAccess::scopeBranch($returns,$request); return response()->json(['data'=>['purchase_total'=>(clone $purchases)->sum('grand_total'),'purchase_count'=>(clone $purchases)->count(),'supplier_due'=>Supplier::where('business_id',$business)->sum('current_due'),'payments'=>$payments->sum('amount'),'returns'=>$returns->sum('total_amount'),'by_supplier'=>(clone $purchases)->selectRaw('supplier_id,SUM(grand_total) total')->with('supplier:id,name')->groupBy('supplier_id')->get()]]); 
    }
    private function documentData(Request $request, bool $invoice): array { return $request->validate(['branch_id'=>['required','integer','exists:branches,id'],'supplier_id'=>['required','integer','exists:suppliers,id'],'document_date'=>['nullable','date'],'purchase_order_id'=>[$invoice?'nullable':'prohibited','integer','exists:purchase_orders,id'],'supplier_invoice_number'=>[$invoice?'nullable':'prohibited','string','max:100'],'discount'=>['nullable','numeric','min:0'],'vat'=>['nullable','numeric','min:0'],'paid_amount'=>[$invoice?'nullable':'prohibited','numeric','min:0'],'notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id'],'items.*.quantity'=>['required','numeric','gt:0'],'items.*.unit_cost'=>['nullable','numeric','min:0']]); }
    private function items(array $rows,int $business): array {$subtotal=0;$items=[];foreach($rows as $row){$product=Product::where('business_id',$business)->findOrFail($row['product_id']);$cost=$row['unit_cost']??$product->purchase_price;$line=$cost*$row['quantity'];$subtotal+=$line;$items[]=compact('product','row','cost','line');}return [$subtotal,$items];}
}
